head.script:
scwin.onpageload = function() {
    window._define_bak = [window.define, window.require, window.requirejs];
    window.define = null;
    window.require = null;
    window.requirejs = null;
    $p.js("https://js.arcgis.com/3.21/", function() {
        require(["esri/map", "dojo/domReady!"], function(res) {
            var map = new res(group1.id, {
                basemap: "topo", //For full list of pre-defined basemaps, navigate to http://arcg.is/1JVo6Wd
                center: [-122.45, 37.75], // longitude, latitude
                zoom: 13
            });
            setTimeout(function() {
                window.define = window._define_bak[0];
                window.require = window._define_bak[1];
                window.requirejs = window._define_bak[2];
                window._define_bak = null;
            }, 1000)
        });
    })
};
scwin.onpageunload = function() {};
